"""A counter built from a closure, not a class."""
from types import SimpleNamespace


def make_counter(start=0, step=1):
    count = start

    def increment():
        nonlocal count      # rebinding the enclosing int requires nonlocal
        count += step
        return count

    def value():
        return count        # reading needs no declaration

    def reset():
        nonlocal count
        count = start
        return count

    return SimpleNamespace(increment=increment, value=value, reset=reset)

